from collections import Counter, defaultdict, deque
from functools import lru_cache


def top_letters(text, n):
    counts = Counter(c for c in text.lower() if "a" <= c <= "z")
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:n]


def by_extension(filenames):
    groups = defaultdict(list)
    for name in filenames:
        ext = name.split(".")[-1].lower() if "." in name else ""
        groups[ext].append(name)
    return {ext: sorted(names) for ext, names in groups.items()}


def moving_average(values, window):
    recent = deque(maxlen=window)
    result = []
    for v in values:
        recent.append(v)
        if len(recent) == window:
            result.append(sum(recent) / window)
    return result


@lru_cache(maxsize=None)
def staircases(n):
    if n <= 1:
        return 1
    return staircases(n - 1) + staircases(n - 2)

