@test("letters")
def _():
    check_eq(top_letters("Hello, world!", 3), [("l", 3), ("o", 2), ("d", 1)])
    check_eq(top_letters("", 2), [])

@test("extensions")
def _():
    files = ["b.TXT", "a.txt", "photo.jpg", "Makefile", "archive.tar.gz", "c.Txt"]
    check_eq(by_extension(files), {"txt": ["a.txt", "b.TXT", "c.Txt"], "jpg": ["photo.jpg"], "": ["Makefile"], "gz": ["archive.tar.gz"]})

@test("moving average")
def _():
    check_eq(moving_average([1, 2, 3, 4], 2), [1.5, 2.5, 3.5])
    check_eq(moving_average([5, 5, 5], 3), [5.0])
    check_eq(moving_average([1, 2], 3), [])

@test("staircases")
def _():
    check_eq([staircases(n) for n in range(1, 7)], [1, 2, 3, 5, 8, 13])
    check_eq(staircases(200), 453973694165307953197296969697410619233826)

